#define _GNU_SOURCE
#include <pthread.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

typedef struct {
    atomic_int refcount;
    int id;
} tstate;

typedef struct {
    tstate *thread;
    int id;
} interpreter_state;

static interpreter_state *global_interpreter;
static pthread_mutex_t head_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_barrier_t observed;
static pthread_barrier_t deletion_released;
static int fixed_mode;
static atomic_int final_refcount = -1;
static int freed_once;

static void *daemon_save_thread(void *unused) {
    (void)unused;
    interpreter_state *victim;
    tstate *ts;

    if (fixed_mode) {
        /* Fixed PyEval_SaveThread path: head_mutex protects the interpreter
         * list lookup and an atomic reference is acquired before unlock. */
        pthread_mutex_lock(&head_mutex);
        victim = global_interpreter;
        if (!victim) {
            fprintf(stderr, "fixed daemon found no interpreter\n");
            exit(2);
        }
        ts = victim->thread;
        atomic_fetch_add_explicit(&ts->refcount, 1, memory_order_acq_rel);
        pthread_mutex_unlock(&head_mutex);
    } else {
        /* Legacy defect: borrowed tstate pointer escapes with neither the
         * list mutex nor an owning reference. */
        victim = global_interpreter;
        ts = victim->thread;
    }

    pthread_barrier_wait(&observed);
    pthread_barrier_wait(&deletion_released);

    int old = atomic_fetch_sub_explicit(&ts->refcount, 1, memory_order_acq_rel);
    atomic_store_explicit(&final_refcount, old - 1, memory_order_release);
    if (fixed_mode) {
        if (old != 1) {
            fprintf(stderr, "fixed final refcount was %d, expected 1\n", old);
            exit(2);
        }
        if (munmap(ts, 4096) != 0) return NULL;
        free(victim);
        freed_once++;
    }
    return NULL;
}

static int run_once(void) {
    global_interpreter = malloc(sizeof(*global_interpreter));
    if (!global_interpreter) return 2;
    global_interpreter->thread = mmap(NULL, 4096, PROT_READ | PROT_WRITE,
                                      MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (global_interpreter->thread == MAP_FAILED) return 2;
    global_interpreter->id = 43;
    global_interpreter->thunlock(&head_mutex);
        if (!tstate) return NULL;
    } else {
        // Defect: an unpinned tstate pointer survives concurrent deletion.
        tstate = interp->tstate;
    }
    announce_save();
    wait_for_stage(2);
    if (!fixed_mode) {
        // Deliberate real UAF in buggy mode: deletion already unmapped this page.
        if (tstate->magic != UINT64_C(0x545354414745)) abort();
    }
    int old = release_tstate(tstate);
    if (fixed_mode && old != 1) abort();
    return NULL;
}
static void *delete_interpreter(void *arg) {
    Interpreter *interp = arg;
    wait_for_stage(1);
    if (fixed_mode) {
        // Fix: unlink/mark deleting and drop the owner ref under head_mutex.
        pthread_mutex_lock(&head_mutex);
        delete_mutex_acquisitions++;
        interp->deleting = true;
        if (head == interp) head = interp->next;
        int old = release_tstate(interp->tstate);
        if (old != 2) { pthread_mutex_unlock(&head_mutex); abort(); }
        pthread_mutex_unlock(&head_mutex);
    } else {
        // Defect: list mutation and owner release race with SaveThread.
        if (head == interp) head = interp->next;
        release_tstate(interp->tstate);
    }
    finish_delete();
    return NULL;
}
int main(int argc, char **argv) {
    if (argc != 2 || (strcmp(argv[1], "--buggy") && strcmp(argv[1], "--fixed"))) return 64;
    fixed_mode = !strcmp(argv[1], "--fixed");
    Interpreter interp = {0};
    interp.tstate = mmap(NULL, 4096, PROT_READ | PROT_WRITE,
                         MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (interp.tstate == MAP_FAILED) return 70;
    atomic_init(&interp.tstate->refs, 1);
    interp.tstate->magic = UINT64_C(0x545354414745);
    head = &interp;
    pthread_t saver, deleter;
    if (pthread_create(&saver, NULL, save_thread, &interp)) return 71;
    if (pthread_create(&deleter, NULL, delete_interpreter, &interp)) return 72;
    pthread_join(saver, NULL);
    pthread_join(deleter, NULL);
    if (fixed_mode) {
        if (save_mutex_acquisitions != 1 || delete_mutex_acquisitions != 1 || head != NULL) return 73;
        puts("FIXED_OK: head_mutex protected save+delete; temporary ref pinned tstate; atomic decrements 2->1->0");
    } else {
        puts("BUGGY_RETURNED_WITHOUT_FAULT: reproduction did not fault");
        return 2;
    }
    return 0;
}
